Use this index.html:
```html
<form id="study"><label>Topic <input id="topic" name="topic"></label><button type="submit">Save</button><output id="result"></output></form>
```
new Event("submit", options) constructs a synthetic cancelable event. dispatchEvent returns false when that event is cancelled, while defaultPrevented becomes true. These observations do not simulate native form constraint validation, a real navigation, or a trusted submit action.
```javascript
function installForm(form, output) {
  function onSubmit(event) {
    event.preventDefault();
    const topic = form.querySelector('[name="topic"]').value.trim();
    output.textContent = topic ? "Saved: " + topic : "Topic required";
  }
  form.addEventListener("submit", onSubmit);
  return () => form.removeEventListener("submit", onSubmit);
}
const form = document.querySelector("#study");
const output = document.querySelector("#result");
const stop = installForm(form, output);
form.querySelector('[name="topic"]').value = "  Maps  ";
const event = new Event("submit", {bubbles: true, cancelable: true});
const allowed = form.dispatchEvent(event);
console.log(allowed, event.defaultPrevented);
console.log(output.textContent);
stop();
```
Output: false true then Saved: Maps.

